import RAPIER from '@dimforge/rapier3d-compat';
import {makeLayout} from './layout.mjs';
import {Simulation} from './simulation.mjs';
import {createView} from './render.mjs';
import {AudioEngine} from './audio.mjs';

const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)];
const audio=new AudioEngine(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let sim,view,mobile=innerWidth<=700,paused=false,dialogPaused=false,hidden=false,graphicsLost=false,accumulator=0,last=performance.now(),activePointer=null,noticeTimeout,uiAt=0,frames=0,physicsSteps=0,frameTimes=[],raf=0,burstAge=10,burstRepeat=false;
const stage=$('#stage'),help=$('#help-dialog');
function wake(){if(!raf&&!hidden&&!graphicsLost&&view){last=performance.now();raf=requestAnimationFrame(frame);}}
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(noticeTimeout);noticeTimeout=setTimeout(()=>$('#notice').classList.remove('show'),2300);}
function syncAudio(){audio.setActive(!paused&&!dialogPaused&&!hidden&&!graphicsLost);}
function soundUI(){const enabled=audio.enabled;$('#sound').setAttribute('aria-pressed',String(enabled));$('#sound').setAttribute('aria-label',enabled?'关闭声音':'开启声音');$('#sound-label').textContent=enabled?'声音开':'声音关';}
function armAudio(){if(audio.enabled)audio.unlock().catch(()=>notify('声音暂未启动，请点击右上角声音按钮重试'));}
function pause(value){paused=value;$('#pause').setAttribute('aria-pressed',String(value));$('#pause').setAttribute('aria-label',value?'恢复模拟':'暂停模拟');$('#pause').title=value?'继续 · P':'暂停 · P';$('#pause-label').textContent=value?'继续':'暂停';$('#pause-icon').innerHTML=value?'<path d="m7 4 8 6-8 6Z"/>':'<path d="M6.5 4.5v11m7-11v11"/>';accumulator=0;last=performance.now();if(value)cancelDrag();syncAudio();updateUI();wake();}
function controls(open,focus=false){$('#controls').hidden=!open;$('#more').setAttribute('aria-expanded',String(open));if(focus)(open?$('#about'):$('#more')).focus();}
$('#more').addEventListener('click',()=>controls($('#controls').hidden,true));$('#close-controls').addEventListener('click',()=>controls(false,true));
document.addEventListener('pointerdown',event=>{if(!$('#controls').hidden&&!event.target.closest('#controls,#more'))controls(false);});
function closeHelp(){help.close();dialogPaused=false;syncAudio();last=performance.now();accumulator=0;wake();}
$('#about').addEventListener('click',()=>{cancelDrag();controls(false);dialogPaused=true;syncAudio();help.showModal();wake();});$('#close-help').addEventListener('click',closeHelp);$('#help-start').addEventListener('click',closeHelp);help.addEventListener('close',()=>{dialogPaused=false;syncAudio();accumulator=0;last=performance.now();$('#more').focus();wake();});
$('#sound').addEventListener('click',async()=>{try{const toggled=audio.toggle();soundUI();const enabled=await toggled;soundUI();notify(enabled?'声音已开启':'声音已关闭');}catch{notify('当前浏览器暂时无法启用声音');}});
$('#retry').addEventListener('click',()=>location.reload());
$('#volume').addEventListener('input',event=>audio.setVolume(event.target.value/100));
$('.wordmark').addEventListener('click',event=>{event.preventDefault();if(sim)rebuild();});

function create(){
 const layout=makeLayout({mobile});sim=new Simulation(RAPIER,layout,{mobile});view=createView($('#canvas-host'),layout,{mobile,reduced});
 const pan=o=>Math.max(-1,Math.min(1,view.screenPoint(o.id).x/innerWidth*2-1));
 sim.onImpact=event=>audio.impact(event,pan(event.item));sim.onSettle=o=>audio.settle(o,pan(o));sim.onRelease=(o,repeat)=>audio.release(o,pan(o),repeat);
 bindPointer();$('#loading').classList.add('loaded');$('#loading').setAttribute('aria-hidden','true');
 view.canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();graphicsLost=true;pause(true);$('#fallback').hidden=false;$('#fallback strong').textContent='图形连接已中断';$('#fallback p').textContent='点击重新加载即可恢复游乐场。';});
}
function cancelDrag(){if(activePointer!==null&&view){try{view.canvas.releasePointerCapture(activePointer);}catch{}activePointer=null;}sim?.endDrag();if(view){view.canvas.classList.remove('dragging');view.setHover(-1);}$('#cursor').classList.remove('visible');}
function bindPointer(){
 const canvas=view.canvas;
 canvas.addEventListener('pointerdown',event=>{
  if(graphicsLost||event.button!==0||activePointer!==null||sim.mode==='rebuilding'||help.open)return;
  const hit=view.pick(event.clientX,event.clientY);if(!hit)return;armAudio();event.preventDefault();pause(false);stage.focus({preventScroll:true});
  burstAge=10;activePointer=event.pointerId;canvas.setPointerCapture(event.pointerId);view.beginPlane(hit.point);sim.startDrag(hit.id,hit.point);canvas.classList.add('dragging');$('#cursor span').textContent='甩开';audio.tone('toggle');updateUI();
 });
 canvas.addEventListener('pointermove',event=>{
  wake();
  const r=canvas.getBoundingClientRect();view.parallax.x=(event.clientX-r.left)/r.width*2-1;view.parallax.y=-((event.clientY-r.top)/r.height*2-1);
  $('#cursor').style.left=`${event.clientX-r.left}px`;$('#cursor').style.top=`${event.clientY-r.top}px`;
  if(activePointer!==null){if(event.pointerId!==activePointer)return;const p=view.projectDrag(event.clientX,event.clientY);if(p)sim.moveDrag(p);return;}
  if(event.pointerType==='touch'||sim.mode==='rebuilding')return;const hit=view.pick(event.clientX,event.clientY);view.setHover(hit?.id??-1);$('#cursor').classList.toggle('visible',!!hit);$('#cursor span').textContent='抓住';canvas.style.cursor=hit?'grab':'default';
 });
 for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,event=>{if(event.pointerId===activePointer){activePointer=null;sim.endDrag();canvas.classList.remove('dragging');$('#cursor span').textContent='抓住';updateUI();wake();}});
 canvas.addEventListener('pointerleave',()=>{if(activePointer===null){view.setHover(-1);$('#cursor').classList.remove('visible');}view.parallax.x=0;view.parallax.y=0;wake();});
 canvas.addEventListener('dblclick',event=>{event.preventDefault();cancelDrag();pulse(view.pointInStage(event.clientX,event.clientY));});
}
function release(){if(!sim||graphicsLost||sim.mode==='rebuilding')return;armAudio();pause(false);sim.setGravity('zero');audio.tone('toggle');updateUI();}
function pulse(point){if(!sim||graphicsLost||sim.mode==='rebuilding')return;armAudio();cancelDrag();pause(false);burstRepeat=sim.mode!=='assembled';audio.tone('pulse');if(sim.pulse(point)){burstAge=0;view.kick(burstRepeat);updateUI();}}
function rebuild(){if(!sim||graphicsLost||sim.mode==='rebuilding')return;armAudio();cancelDrag();pause(false);burstAge=10;sim.rebuild();updateUI();}
function gravity(direction){if(!sim||graphicsLost||sim.mode==='rebuilding')return;armAudio();cancelDrag();pause(false);sim.setGravity(direction);audio.tone('toggle');updateUI();}
$('#release').addEventListener('click',()=>pulse());$('#pulse').addEventListener('click',()=>pulse());$('#rebuild').addEventListener('click',rebuild);$('#pause').addEventListener('click',()=>pause(!paused));$$('[data-gravity]').forEach(button=>button.addEventListener('click',()=>gravity(button.dataset.gravity)));
addEventListener('keydown',event=>{
 if(event.key==='Escape'&&!$('#controls').hidden){controls(false,true);return;}
 if(!sim||graphicsLost||help.open||event.ctrlKey||event.metaKey||event.altKey||event.repeat)return;
 if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;
 const key=event.key.toLowerCase();if((key===' '||key==='enter')&&document.activeElement.tagName==='BUTTON')return;
 const handlers={g:release,r:rebuild,p:()=>pause(!paused),' ':()=>pulse(),arrowleft:()=>gravity('left'),arrowdown:()=>gravity('down'),arrowright:()=>gravity('right'),arrowup:()=>gravity('zero')};
 if(handlers[key]){event.preventDefault();handlers[key]();}
});
function updateUI(){
 if(graphicsLost){$$('#release,#pulse,#rebuild,#pause,[data-gravity]').forEach(button=>button.disabled=true);$('#live-state').textContent='图形连接已中断，请重新加载';return;}
 if(!sim)return;const s=sim.snapshot(),rebuilding=s.mode==='rebuilding',assembled=s.mode==='assembled';
 $('#release').disabled=rebuilding;$('#pulse').disabled=rebuilding;$('#rebuild').disabled=rebuilding;$('#pause').disabled=false;
 $('#release-label').textContent=rebuilding?'复原中':assembled?'释放':'再释放';
 $('#rebuild-progress').style.transform=`scaleX(${rebuilding?s.rebuildProgress:0})`;
 const state=paused?'模拟已暂停':rebuilding?'正在重新组装':assembled?'准备就绪，可以拖动或释放':'字母已释放，可以拖动';if($('#live-state').textContent!==state)$('#live-state').textContent=state;
 document.body.dataset.mode=s.mode;
 $$('[data-gravity]').forEach(b=>{b.disabled=rebuilding;b.setAttribute('aria-pressed',String(b.dataset.gravity===s.gravity));});
}
let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!view||graphicsLost)return;const next=innerWidth<=700;if(next!==mobile){cancelDrag();view.dispose();sim.dispose();mobile=next;create();accumulator=0;burstAge=10;updateUI();}else view.resize();wake();},160);});
document.addEventListener('visibilitychange',()=>{hidden=document.hidden;syncAudio();cancelDrag();accumulator=0;last=performance.now();if(!hidden)wake();});
function frame(now){
 raf=0;const raw=(now-last)/1000,dt=Math.min(raw,.06);last=now;if(hidden||graphicsLost)return;
 if(!paused&&!dialogPaused&&sim.mode!=='assembled'){burstAge+=dt;const scale=!reduced&&!burstRepeat&&burstAge>.12&&burstAge<.62?.6:1;accumulator+=dt*scale;let steps=0;while(accumulator>=1/60&&steps<4){sim.step();accumulator-=1/60;steps++;physicsSteps++;}}else accumulator=0;
 if(view.draw(sim,paused||dialogPaused||sim.mode==='assembled'?1:accumulator/(1/60),dt,paused||dialogPaused)){frames++;if(raw<.2){frameTimes.push(raw*1000);if(frameTimes.length>300)frameTimes.shift();}}
 if(now-uiAt>110||document.body.dataset.mode!==sim.mode){updateUI();uiAt=now;}
 if((!paused&&!dialogPaused&&sim.mode!=='assembled')||view.isAnimating())raf=requestAnimationFrame(frame);
}
async function boot(){
 try{
  if(new URLSearchParams(location.search).has('no-webgl'))throw new Error('WebGL fallback requested');
  await RAPIER.init();create();updateUI();last=performance.now();raf=requestAnimationFrame(frame);
  window.__gravity={ready:true,version:'atelier-v3.5',audio:()=>audio.stats(),captureAudio:()=>audio.captureStream(),snapshot:()=>({...sim.snapshot(),paused,mobile,reduced,frames,physicsSteps,render:view.stats(),meanFrameMs:frameTimes.reduce((a,b)=>a+b,0)/Math.max(1,frameTimes.length)}),screenPoint:id=>view.screenPoint(id),pickPoint:id=>view.pickPoint(id),screenBounds:()=>view.screenBounds(),positions:()=>sim.items.map(o=>({...o.position})),pick:(x,y)=>view.pick(x,y)?.id??null};
 }catch(error){console.error(error);$('#loading').classList.add('loaded');$('#fallback').hidden=false;$('#release').disabled=true;$('#pulse').disabled=true;$('#rebuild').disabled=true;$('#pause').disabled=true;$$('[data-gravity]').forEach(b=>b.disabled=true);$('#live-state').textContent='图形功能不可用';}
}
boot();
